package nl.dwmarketing.callerid;
import android.content.Context;import org.json.*;import java.net.*;import javax.net.ssl.HttpsURLConnection;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
final class SyncClient {
 private static String base()throws Exception{String b=BuildConfig.BACKEND;URI u=new URI(b);if(!"https".equals(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null||u.getQuery()!=null||u.getFragment()!=null)throw new Exception("Productieconfiguratie ontbreekt");return b.replaceAll("/$","");}
 private static JSONObject post(String path,JSONObject body,String token,boolean signed)throws Exception{
  HttpsURLConnection c=(HttpsURLConnection)new URL(base()+path).openConnection();c.setInstanceFollowRedirects(false);c.setRequestMethod("POST");c.setConnectTimeout(8000);c.setReadTimeout(8000);c.setRequestProperty("apikey",BuildConfig.PUBLIC_KEY);c.setRequestProperty("Content-Type","application/json");if(token!=null)c.setRequestProperty("Authorization","Bearer "+token);
  if(signed){String time=Long.toString(System.currentTimeMillis()),nonce=UUID.randomUUID().toString();c.setRequestProperty("X-DW-Time",time);c.setRequestProperty("X-DW-Nonce",nonce);c.setRequestProperty("X-DW-Signature",PrivateStore.sign("DW-CALLER-SYNC\n"+time+"\n"+nonce));}
  try{c.setDoOutput(true);try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}int code=c.getResponseCode();if(code!=200){if(code==401||code==403)throw new SecurityException("Sessie of apparaat niet toegestaan");throw new IOException("Synchronisatie niet bevestigd");}try(InputStream in=c.getInputStream();ByteArrayOutputStream bytes=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(bytes.size()+n>10000000)throw new IOException("Te groot");bytes.write(b,0,n);}return new JSONObject(bytes.toString("UTF-8"));}}finally{c.disconnect();}
 }
 static synchronized void logout(Context c){PrivateStore.clear(c);c.getSystemService(android.app.job.JobScheduler.class).cancel(SyncJob.ID);c.getSystemService(android.app.NotificationManager.class).cancel(DwScreeningService.NOTICE);}
 static synchronized void login(Context c,String email,String password)throws Exception{try{JSONObject session=post("/auth/v1/token?grant_type=password",new JSONObject().put("email",email).put("password",password),null,false);PrivateStore.put(c,"session",new JSONObject().put("access_token",session.getString("access_token")).put("refresh_token",session.getString("refresh_token")));sync(c);}catch(Exception e){PrivateStore.clear(c);throw e;}}
 static synchronized void sync(Context c)throws Exception{JSONObject s=PrivateStore.get(c,"session");if(s==null)throw new SecurityException("Meld je aan");try{JSONObject fresh=post("/auth/v1/token?grant_type=refresh_token",new JSONObject().put("refresh_token",s.getString("refresh_token")),null,false);PrivateStore.put(c,"session",new JSONObject().put("access_token",fresh.getString("access_token")).put("refresh_token",fresh.getString("refresh_token")));JSONObject snapshot=post("/functions/v1/dw-caller-id",new JSONObject(),fresh.getString("access_token"),true);if(snapshot.optInt("version")!=1||snapshot.optLong("expires_at")<=System.currentTimeMillis())throw new IOException("Snapshot niet geldig");PrivateStore.put(c,"snapshot",snapshot);}catch(SecurityException e){PrivateStore.clear(c);throw e;}}
}
